"""PDF185 printed364–365: Figure 24.2 EM spectrum, 24.2.2 spectroscopic methods, 24.2.2.1 UV-Vis — electronic transitions (Figure 24.3)."""
from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
F=Fig('arrow185');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def lines(rows,kind='list'):
 s0=len(paras)
 for r in rows:paras.append(pair(*r))
 layout.append({'type':kind,'indices':list(range(s0,len(paras)))})
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def ems(lang):
 s=F.start(300)+t(90,24,K(lang,'Highest energy','سب سے زیادہ توانائی','تر ټولو لوړه انرژي'),12)+t(760,24,K(lang,'Lowest energy','سب سے کم توانائی','تر ټولو ټیټه انرژي'),12)
 bands=[(40,120,'Gamma ray','گاما شعاع','ګاما وړانګه','#90a4ae'),(120,230,'X-ray','ایکس رے','ایکس وړانګه','#b0bec5'),(230,275,'Ultra-violet','بالائے بنفشی','ماورای بنفش','#ce93d8'),(275,290,'','','','#fff176'),(290,440,'Infrared','زیریں سرخ','زیرسره','#bcaaa4'),(440,580,'Microwave','مائیکرو ویو','مایکروویو','#cfd8dc'),(580,810,'Radio frequency','ریڈیائی تعدد','راډیويي فریکونسي','#eceff1')]
 for a,b,e,u,p,c in bands:s+=f'<rect x="{a}" y="60" width="{b-a}" height="40" fill="{c}" stroke="#555"/>'+t((a+b)/2,85,K(lang,e,u,p),11)
 s+=t(283,52,K(lang,'Visible','مرئی','لیدونکی'),9)
 for i,x in enumerate(range(80,800,100)):s+=t(x,48,'10'+['⁻²','⁰','²','⁴','⁶','⁸','¹⁰','¹²'][i],11)
 for i,x in enumerate(range(80,810,90)):s+=t(x,118,f'10{["²⁰","¹⁸","¹⁶","¹⁴","¹²","¹⁰","⁸","⁶","⁴"][i]}',11)
 s+=t(430,38,K(lang,'Wavelength (nm) →','طولِ موج (nm) →','د موج اوږدوالی (nm) →'),12)+t(700,136,K(lang,'← Frequency (s⁻¹)','← تعدد (s⁻¹)','← فریکونسي (s⁻¹)'),12)
 cols=['#3949ab','#1e88e5','#00acc1','#43a047','#c0ca33','#fdd835','#fb8c00','#f4511e','#e53935','#b71c1c']
 s+=''.join(f'<rect x="{180+i*52}" y="190" width="52" height="50" fill="{c}"/>' for i,c in enumerate(cols))+line(283,100,180,190,1,'#999')+line(290,100,700,190,1,'#999')
 for nm in (400,500,600,700,750):x=180+(nm-400)/350*520;s+=t(x,182,f'{nm}'+(' nm' if nm==750 else ''),11)
 s+=t(440,262,K(lang,'Visible region','مرئی خطہ','لیدونکې سیمه'),12)
 return s+'</svg>'
def levels(lang):
 s=F.start(260)+t(40,24,'E',14)+line(40,240,40,30,1.5)+'<path d="M34 40 L40 28 L46 40 Z" fill="#222"/>'
 L=[('σ*',40),('π*',80),('n',150),('π',190),('σ',230)]
 for lab,y in L:s+=line(60,y,640,y,1.5)+t(670,y+5,lab,14)
 for x,a,b,lab in ((150,150,80,'n→π*'),(280,190,80,'π→π*'),(410,150,40,'n→σ*'),(560,230,40,'σ→σ*')):
  s+=line(x,a,x,b+8,1.8)+f'<path d="M{x-6} {b+10} L{x} {b} L{x+6} {b+10} Z" fill="#222"/>'+t(x+40,(a+b)/2,lab,12)
 return s+'</svg>'

visual('chem12-figure24-2',ems)
add('Figure 24.2 The electromagnetic spectrum.','شکل 24.2 برقی مقناطیسی طیف۔','شکل 24.2 برېښنايي مقناطیسي طیف.')
add('24.2.2 Spectroscopic Methods','24.2.2 سپیکٹروسکوپی طریقے','24.2.2 سپکټروسکوپي طریقې','heading')
add('This book covers the Ultraviolet-Visible (UV–Vis) Spectroscopy, Infrared (IR) Spectroscopy, Nuclear Magnetic Resonance (NMR) Spectroscopy and Mass Spectrometry (MS) that serve as powerful tools for structure and molecular mass determination. This unit also includes Atomic Emission and Atomic Absorption Spectroscopy, which are used for qualitative and quantitative analysis of elements.','یہ کتاب بالائے بنفشی–مرئی (UV–Vis) سپیکٹروسکوپی، زیریں سرخ (IR) سپیکٹروسکوپی، نیوکلیئر میگنیٹک ریزونینس (NMR) سپیکٹروسکوپی اور ماس سپیکٹرومیٹری (MS) کا احاطہ کرتی ہے جو ساخت اور سالماتی کمیت کے تعین کے طاقتور اوزار ہیں۔ اس یونٹ میں جوہری اخراجی اور جوہری جذبی سپیکٹروسکوپی بھی شامل ہے جو عناصر کے کیفیتی اور مقداری تجزیے کے لیے استعمال ہوتی ہیں۔','دا کتاب ماورای بنفش–لیدونکې (UV–Vis) سپکټروسکوپي، زیرسره (IR) سپکټروسکوپي، د هستوي مقناطیسي ریزونانس (NMR) سپکټروسکوپي او ماس سپکټرومیټري (MS) پوښي چې د جوړښت او مالیکولي کتلې د ټاکلو لپاره پیاوړې وسیلې دي. دا واحد اټومي خپرونه او اټومي جذب سپکټروسکوپي هم لري چې د عناصرو د کیفي او کمي تحلیل لپاره کارېږي.')
add('Tidbit','مختصر معلومات','لنډ معلومات','heading')
add('A spectrometer is a device used to detect spectrum of a substance in a range; for example, a range of mass-to-charge values as in mass spectrometry or a range of wavelengths as in absorption spectrometry like infrared spectroscopy etc. A spectrophotometer is spectrometer that only measures the intensity of electromagnetic radiations absorbed (and transmitted) by a material.','سپیکٹرومیٹر ایک آلہ ہے جو کسی مادے کا طیف ایک حد میں معلوم کرنے کے لیے استعمال ہوتا ہے؛ مثلاً ماس سپیکٹرومیٹری میں کمیت اور چارج کی نسبت کی حد یا زیریں سرخ سپیکٹروسکوپی جیسی جذبی سپیکٹرومیٹری میں طولِ موج کی حد۔ سپیکٹرو فوٹومیٹر وہ سپیکٹرومیٹر ہے جو صرف کسی مادے کی طرف سے جذب (اور منتقل) ہونے والی برقی مقناطیسی شعاعوں کی شدت ناپتا ہے۔','سپکټرومیټر یوه وسیله ده چې د یوې مادې طیف په یوه پوله کې موندلو لپاره کارېږي؛ د بېلګې په توګه په ماس سپکټرومیټري کې د کتلې–چارج د ارزښتونو پوله یا په جذب سپکټرومیټري لکه زیرسره سپکټروسکوپي کې د موج د اوږدوالي پوله. سپکټروفوټومیټر هغه سپکټرومیټر دی چې یوازې د یوې مادې له خوا د جذب شویو (او تېرو شویو) برېښنايي مقناطیسي وړانګو شدت اندازه کوي.')
add('24.2.2.1 Ultraviolet-Visible (U.V–Vis) Spectroscopy','24.2.2.1 بالائے بنفشی–مرئی (U.V–Vis) سپیکٹروسکوپی','24.2.2.1 ماورای بنفش–لیدونکې (U.V–Vis) سپکټروسکوپي','heading')
add('Absorption of electromagnetic radiation by a molecule in ultraviolet (10–400 nm) and visible (400–750 nm) region leads to electronic transitions. It is therefore, discussed together as Ultraviolet-Visible spectroscopy. This technique is also called electronic spectroscopy. Normal U.V-Visible spectrometer uses near ultraviolet region of ultraviolet radiation which has wavelength range of 200 nm to 400 nm.','بالائے بنفشی (10–400 nm) اور مرئی (400–750 nm) خطے میں کسی سالمے کی طرف سے برقی مقناطیسی شعاعوں کا جذب الیکٹرانی منتقلیوں کا باعث بنتا ہے۔ اس لیے ان پر بالائے بنفشی–مرئی سپیکٹروسکوپی کے طور پر اکٹھے بحث کی جاتی ہے۔ اس تکنیک کو الیکٹرانی سپیکٹروسکوپی بھی کہتے ہیں۔ عام U.V-مرئی سپیکٹرومیٹر بالائے بنفشی شعاعوں کا قریبی بالائے بنفشی خطہ استعمال کرتا ہے جس کی طولِ موج کی حد 200 nm سے 400 nm ہے۔','په ماورای بنفش (10–400 nm) او لیدونکې (400–750 nm) سیمه کې د یوه مالیکول له خوا د برېښنايي مقناطیسي وړانګو جذب الکتروني انتقالونو ته لار هواروي. له همدې امله د ماورای بنفش–لیدونکې سپکټروسکوپي په توګه یو ځای څېړل کېږي. دې تخنیک ته الکتروني سپکټروسکوپي هم وايي. عادي U.V-لیدونکی سپکټرومیټر د ماورای بنفش وړانګو نږدې ماورای بنفش سیمه کاروي چې د موج اوږدوالی یې له 200 nm تر 400 nm دی.')
add('Absorption in Ultraviolet/Visible Radiations and Electronic Transitions','بالائے بنفشی/مرئی شعاعوں میں جذب اور الیکٹرانی منتقلیاں','په ماورای بنفش/لیدونکو وړانګو کې جذب او الکتروني انتقالونه','heading')
add('Absorption of UV-Visible radiations by a molecule is associated with excitation of electron from ground to excited states. The common electronic transition that are associated with the absorption of UV-Vis radiation by organic molecules, are of four types i.e. σ→σ*, n→σ*, π→π* and n→π*, as shown in Figure 24.3.','سالمے کی طرف سے UV-مرئی شعاعوں کا جذب الیکٹران کے زمینی حالت سے ہیجانی حالتوں میں جانے سے وابستہ ہے۔ نامیاتی سالمات کی طرف سے UV-Vis شعاعوں کے جذب سے وابستہ عام الیکٹرانی منتقلیاں چار قسم کی ہیں یعنی σ→σ*، n→σ*، π→π* اور n→π*، جیسا کہ شکل 24.3 میں دکھایا گیا ہے۔','د یوه مالیکول له خوا د UV-لیدونکو وړانګو جذب له ځمکني حالت څخه هڅول شوو حالتونو ته د الکترون له هڅولو سره تړلی دی. هغه عام الکتروني انتقالونه چې د عضوي مالیکولونو له خوا د UV-Vis وړانګو له جذب سره تړلي دي څلور ډوله دي یعنې σ→σ*، n→σ*، π→π* او n→π*، لکه څنګه چې په شکل 24.3 کې ښودل شوي.')
visual('chem12-figure24-3',levels)
add('Figure 24.3 Common types of electronic transition in organic molecules.','شکل 24.3 نامیاتی سالمات میں الیکٹرانی منتقلی کی عام اقسام۔','شکل 24.3 په عضوي مالیکولونو کې د الکتروني انتقال عام ډولونه.')
lines([('i. The σ→σ* transitions occur in saturated hydrocarbons such as alkanes and cycloalkanes which contain only sigma bonds. σ→σ* transition requires greater energy, thus C–C bond absorbs at 135 nm and C–H bond absorbs at about 125 nm.','i. σ→σ* منتقلیاں سیر شدہ ہائیڈروکاربنز جیسے الکینز اور سائیکلو الکینز میں ہوتی ہیں جن میں صرف سگما بند ہوتے ہیں۔ σ→σ* منتقلی کو زیادہ توانائی درکار ہوتی ہے، اس لیے C–C بند 135 nm پر اور C–H بند تقریباً 125 nm پر جذب کرتا ہے۔','i. σ→σ* انتقالونه په مشبوعو هایدروکاربنونو لکه الکانونو او سایکلو الکانونو کې کېږي چې یوازې سیګما تړونونه لري. σ→σ* انتقال ډېرې انرژۍ ته اړتیا لري، نو C–C تړون په 135 nm او C–H تړون په نږدې 125 nm کې جذب کوي.'),
 ('ii. The n→σ* transitions occur in a saturated molecules containing heteroatoms, such as oxygen, sulphur, nitrogen or halogens. This transition requires slightly less energy than required for σ→σ* transition. For example methyl alcohol shows n→σ* absorption at 183 nm.','ii. n→σ* منتقلیاں آکسیجن، سلفر، نائٹروجن یا ہیلوجنز جیسے ہیٹرو ایٹم رکھنے والے سیر شدہ سالمات میں ہوتی ہیں۔ اس منتقلی کو σ→σ* منتقلی سے کچھ کم توانائی درکار ہوتی ہے۔ مثلاً میتھائل الکوحل 183 nm پر n→σ* جذب ظاہر کرتا ہے۔','ii. n→σ* انتقالونه په هغو مشبوعو مالیکولونو کې کېږي چې هېټرو اټومونه لکه اکسیجن، سلفر، نایټروجن یا هالوجنونه لري. دا انتقال د σ→σ* انتقال په پرتله لږ کمې انرژۍ ته اړتیا لري. د بېلګې په توګه میتایل الکول په 183 nm کې n→σ* جذب ښيي.'),
 ('iii. The π→π* transitions occur in molecule, containing double or triple bonds or aromatic rings. For example ethylene absorbs at 171nm for π→π* transition. However, a conjugated system of unsaturated bonds absorbs at much longer wavelength, e.g. buta-1,3-diene and isoprene (2-methylbuta-1,3-diene) shows maximum absorption at 217 nm and 222 nm respectively (Figure 24.4).','iii. π→π* منتقلیاں دوہرے یا تہرے بند یا ارومیٹک رنگ رکھنے والے سالمے میں ہوتی ہیں۔ مثلاً ایتھیلین π→π* منتقلی کے لیے 171nm پر جذب کرتی ہے۔ تاہم غیر سیر شدہ بندوں کا مزدوج نظام کہیں زیادہ طولِ موج پر جذب کرتا ہے، مثلاً بیوٹا-1،3-ڈائین اور آئسوپرین (2-میتھائل بیوٹا-1،3-ڈائین) بالترتیب 217 nm اور 222 nm پر زیادہ سے زیادہ جذب ظاہر کرتے ہیں (شکل 24.4)۔','iii. π→π* انتقالونه په هغه مالیکول کې کېږي چې دوه ګوني یا درې ګوني تړونونه یا اروماتیک حلقې لري. د بېلګې په توګه ایتیلین د π→π* انتقال لپاره په 171nm کې جذب کوي. خو د نامشبوعو تړونونو مزدوج سیستم په ډېر اوږده موج کې جذب کوي، لکه بیوټا-1،3-ډاین او ایزوپرین (2-میتایل بیوټا-1،3-ډاین) په ترتیب سره په 217 nm او 222 nm کې اعظمي جذب ښيي (شکل 24.4).'),
 ('iv. The n→π* transitions occur in molecules that contain double or triple bonds involving hetero atoms such as aldehydes, ketones, nitriles etc. The n→π* absorption band for acetone appears at 279 nm.','iv. n→π* منتقلیاں ان سالمات میں ہوتی ہیں جن میں ہیٹرو ایٹموں والے دوہرے یا تہرے بند ہوں جیسے الڈیہائیڈز، کیٹونز، نائٹرائلز وغیرہ۔ ایسیٹون کے لیے n→π* جذبی پٹی 279 nm پر ظاہر ہوتی ہے۔','iv. n→π* انتقالونه په هغو مالیکولونو کې کېږي چې د هېټرو اټومونو لرونکي دوه ګوني یا درې ګوني تړونونه لري لکه الدیهایډونه، کیټونونه، نایټرایلونه او نور. د اسیتون لپاره n→π* جذب بانډ په 279 nm کې ښکاري.')],'lines')
add('The d–d transitions (Section 14.2.4) of transition metal complexes occurs usually in visible region. The colour of transition metal complexes are usually coloured due to d–d transition. When a substance absorb a particular wavelength in visible region, the colour that our eyes perceives is not the colour corresponding to the wavelength of the light absorbed but its complementary colour that is transmitted. We can also predict the possible colour of a transition metal complex from its UV–Visible spectrum showing its absorption wavelength, using Table 24.1.','عبوری دھاتی کمپلیکسز کی d–d منتقلیاں (حصہ 14.2.4) عموماً مرئی خطے میں ہوتی ہیں۔ عبوری دھاتی کمپلیکسز عموماً d–d منتقلی کی وجہ سے رنگین ہوتے ہیں۔ جب کوئی مادہ مرئی خطے میں کوئی خاص طولِ موج جذب کرتا ہے تو ہماری آنکھیں جو رنگ دیکھتی ہیں وہ جذب شدہ روشنی کی طولِ موج کا رنگ نہیں بلکہ اس کا تکمیلی رنگ ہوتا ہے جو منتقل ہوتا ہے۔ ہم جدول 24.1 استعمال کر کے کسی عبوری دھاتی کمپلیکس کا ممکنہ رنگ اس کے جذبی طولِ موج دکھانے والے UV–مرئی طیف سے بھی پیش گوئی کر سکتے ہیں۔','د انتقالي فلزي کمپلېکسونو d–d انتقالونه (برخه 14.2.4) معمولاً په لیدونکې سیمه کې کېږي. انتقالي فلزي کمپلېکسونه معمولاً د d–d انتقال له امله رنګه وي. کله چې یوه ماده په لیدونکې سیمه کې یو ټاکلی موج اوږدوالی جذب کړي، هغه رنګ چې زموږ سترګې یې ویني د جذب شوې رڼا د موج اوږدوالي رنګ نه بلکې د هغه بشپړوونکی رنګ دی چې تېرېږي. موږ کولی شو د جدول 24.1 په کارولو د یوه انتقالي فلزي کمپلېکس ممکنه رنګ د هغه له UV–لیدونکي طیف چې د جذب موج اوږدوالی ښيي وړاندوینه کړو.')
add('Tidbit','مختصر معلومات','لنډ معلومات','heading')
add('Lycopene, a pigment in ripped tomatoes, has a conjugated system of 11 double bonds and absorbs visible light. Its longest wavelength absorption is at 505 nm.','لائیکوپین، پکے ٹماٹروں کا ایک پگمنٹ، 11 دوہرے بندوں کا مزدوج نظام رکھتا ہے اور مرئی روشنی جذب کرتا ہے۔ اس کا سب سے لمبی طولِ موج کا جذب 505 nm پر ہے۔','لایکوپین، په پخو رومیانو کې یو پیګمنټ، د 11 دوه ګونو تړونونو مزدوج سیستم لري او لیدونکې رڼا جذبوي. د تر ټولو اوږده موج جذب یې په 505 nm کې دی.')
